-- PR3: extend the canonical evidence model; no parallel submission system.
alter table public.vc_university_evidence_definition_versions
 add column if not exists form_schema jsonb not null default '{}' check(jsonb_typeof(form_schema)='object'),
 add column if not exists validation_policy jsonb not null default '{}' check(jsonb_typeof(validation_policy)='object');
alter table public.vc_university_evidence_submissions
 add column if not exists draft_data jsonb not null default '{}' check(jsonb_typeof(draft_data)='object'),
 add column if not exists draft_version integer not null default 0 check(draft_version>=0),
 add column if not exists review_selected boolean not null default false;
alter table public.vc_university_evidence_revisions
 add column if not exists structured_data jsonb check(structured_data is null or jsonb_typeof(structured_data)='object'),
 add column if not exists request_id uuid,
 add constraint evidence_revision_request_unique unique(submission_id,request_id),
 add constraint evidence_revision_submission_identity unique(evidence_revision_id,submission_id);
alter table public.vc_university_evidence_reviews
 add constraint evidence_review_revision_context foreign key(evidence_revision_id,submission_id)
 references public.vc_university_evidence_revisions(evidence_revision_id,submission_id);
create index if not exists evidence_review_context_idx on public.vc_university_evidence_reviews(evidence_revision_id,submission_id);
-- Preserve the legacy content limit, permit bounded structured payloads.
alter table public.vc_university_evidence_revisions drop constraint vc_university_evidence_revisions_content_check;
alter table public.vc_university_evidence_revisions add constraint vc_university_evidence_revisions_content_check
 check ((structured_data is null and length(btrim(content)) between 20 and 12000)
 or (structured_data is not null and octet_length(structured_data::text)<=65536 and content='Structured evidence; see structured_data'));
alter table public.vc_university_evidence_submissions add constraint evidence_draft_size check(octet_length(draft_data::text)<=65536);

-- Versioned definitions cannot change after they are published or used.
create or replace function public.vc_university_guard_evidence_definition() returns trigger
language plpgsql security invoker set search_path='' as $$
begin
 if (old.status in ('published','archived') or exists(select 1 from public.vc_university_evidence_submissions s
 where s.evidence_definition_version_id=old.evidence_definition_version_id)) and
 (to_jsonb(new)-'status') is distinct from (to_jsonb(old)-'status') then
 raise exception 'evidence_definition_version_immutable'; end if;
 return new;
end $$;
create trigger evidence_definition_version_guard before update on public.vc_university_evidence_definition_versions
 for each row execute function public.vc_university_guard_evidence_definition();

create or replace function vc_private.vc_university_teacher_can_review(p_actor uuid,p_submission uuid)
returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.vc_university_evidence_submissions s
 join public.vc_university_enrollments e on e.enrollment_id=s.enrollment_id
 join public.vc_university_teachers t on t.cohort_id=e.cohort_id
 join public.vc_university_evidence_definition_versions d on d.evidence_definition_version_id=s.evidence_definition_version_id
 where s.submission_id=p_submission and t.user_id=p_actor and s.learner_id<>p_actor
 and d.validation_mode in ('sampled','human_required') and s.review_selected
 and s.current_revision>0 and s.status<>'draft');
$$;
revoke all on function vc_private.vc_university_teacher_can_review(uuid,uuid) from public,anon,authenticated;
grant execute on function vc_private.vc_university_teacher_can_review(uuid,uuid) to service_role;
create or replace function vc_private.vc_university_can_read_submission(p_submission_id uuid)
returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.vc_university_evidence_submissions s
 where s.submission_id=p_submission_id and s.learner_id=(select auth.uid()))
 or vc_private.vc_university_teacher_can_review((select auth.uid()),p_submission_id);
$$;

-- Structural validation only. No semantic/psychological assessment.
create or replace function public.vc_university_validate_evidence_fields(p_fields jsonb,p_data jsonb)
returns boolean language plpgsql immutable security invoker set search_path='' as $$
declare f jsonb; v jsonb; k text; n numeric;
begin
 if jsonb_typeof(p_data) is distinct from 'object' then return false; end if;
 for f in select value from jsonb_array_elements(p_fields) loop
 k:=f->>'field_key'; v:=p_data->k;
 if v is null or v='null'::jsonb or v='""'::jsonb then
 if coalesce((f->>'required')::boolean,false) then return false; else continue; end if; end if;
 if f->>'type'='number' then
 if jsonb_typeof(v)<>'number' then return false; end if;
 n:=(v#>>'{}')::numeric;
 if n<(f->>'min')::numeric or n>(f->>'max')::numeric or
 (coalesce((f->'validation_rules'->>'integer')::boolean,false) and n<>trunc(n)) then return false; end if;
 elsif f->>'type'='select' then
 if jsonb_typeof(v)<>'string' or not exists(select 1 from jsonb_array_elements(f->'options') o where o->>'value'=v#>>'{}') then return false; end if;
 else
 if jsonb_typeof(v)<>'string' or length(btrim(v#>>'{}'))<coalesce((f->>'min')::integer,0)
 or length(v#>>'{}')>coalesce((f->>'max')::integer,1200) then return false; end if;
 end if;
 end loop;
 if exists(select 1 from jsonb_object_keys(p_data) x where not exists(select 1 from jsonb_array_elements(p_fields) f where f->>'field_key'=x)) then return false; end if;
 return true;
end $$;
create or replace function public.vc_university_validate_evidence(p_schema jsonb,p_data jsonb)
returns boolean language plpgsql immutable security invoker set search_path='' as $$
declare s jsonb; item jsonb; fields jsonb:='[]'; repeats text[]:=array[]::text[]; flat jsonb;
begin
 if jsonb_typeof(p_data) is distinct from 'object' or octet_length(p_data::text)>65536
 or jsonb_typeof(p_schema->'sections') is distinct from 'array' then return false; end if;
 flat:=p_data;
 for s in select value from jsonb_array_elements(p_schema->'sections') loop
 if coalesce((s->>'repeatable')::boolean,false) then
 repeats:=array_append(repeats,s->>'section_key'); item:=p_data->(s->>'section_key');
 if jsonb_typeof(item) is distinct from 'array' then return false; end if;
 if jsonb_array_length(item)<(s->>'min_items')::integer or jsonb_array_length(item)>(s->>'max_items')::integer then return false; end if;
 for item in select value from jsonb_array_elements(item) loop
 if not public.vc_university_validate_evidence_fields(s->'fields',item) then return false; end if;
 end loop;
 flat:=flat-(s->>'section_key');
 else fields:=fields||(s->'fields'); end if;
 end loop;
 return public.vc_university_validate_evidence_fields(fields,flat);
end $$;

create or replace function public.vc_university_evidence_requirement(p_submission uuid,p_satisfied boolean)
returns void language plpgsql security invoker set search_path='' as $$
declare s public.vc_university_evidence_submissions%rowtype; r record; rev uuid;
begin
 select * into s from public.vc_university_evidence_submissions where submission_id=p_submission;
 select evidence_revision_id into rev from public.vc_university_evidence_revisions where submission_id=p_submission and revision=s.current_revision;
 for r in select mr.* from public.vc_university_module_requirements mr
 join public.vc_university_evidence_definition_versions dv on dv.evidence_definition_version_id=s.evidence_definition_version_id
 join public.vc_university_evidence_definitions d on d.evidence_definition_id=dv.evidence_definition_id
 join public.vc_university_module_versions mv on mv.module_id=d.module_id and mv.course_id=s.course_id and mv.course_version=s.course_version
 where mr.module_version_id=mv.module_version_id and mr.status='published' and mr.requirement_type='evidence_completed'
 and mr.configuration->>'evidence_definition_version_id'=dv.evidence_definition_version_id::text loop
 insert into public.vc_university_requirement_progress(enrollment_id,requirement_id,status,source_type,source_id,satisfied_at)
 values(s.enrollment_id,r.requirement_id,case when p_satisfied then 'completed' else 'requirements_pending' end,'evidence_revision',rev::text,case when p_satisfied then now() else null end)
 on conflict(enrollment_id,requirement_id) do update set status=excluded.status,source_type=excluded.source_type,source_id=excluded.source_id,satisfied_at=excluded.satisfied_at,updated_at=now();
 if p_satisfied then
 insert into public.vc_university_academic_audit_log(actor_id,action,entity_type,entity_id,after_state)
 values(s.learner_id,'requirement_satisfied','requirement',r.requirement_id::text,jsonb_build_object('submission_id',p_submission,'revision_id',rev));
 -- Completion always goes through the approved PR2 engine.
 perform public.vc_university_complete_module_if_ready(s.enrollment_id,r.module_version_id);
 end if;
 end loop;
end $$;

-- All draft and submission changes are atomic, locked and service-only.
create or replace function public.vc_university_evidence_write(
 p_actor uuid,p_enrollment uuid,p_module uuid,p_action text,p_payload jsonb,
 p_expected_version integer,p_request_id uuid default null)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare e public.vc_university_enrollments%rowtype; m public.vc_university_module_versions%rowtype;
 d public.vc_university_evidence_definition_versions%rowtype; s public.vc_university_evidence_submissions%rowtype;
 rev public.vc_university_evidence_revisions%rowtype; created boolean:=false; sufficient boolean; ev text;
begin
 if p_action not in ('draft','submit') then raise exception 'invalid_evidence_action'; end if;
 select * into e from public.vc_university_enrollments where enrollment_id=p_enrollment and user_id=p_actor and status='active';
 select * into m from public.vc_university_module_versions where module_version_id=p_module and course_id=e.course_id and course_version=e.course_version and status='published';
 if e.enrollment_id is null or m.module_version_id is null then raise exception 'evidence_context_denied'; end if;
 if exists(select 1 from public.vc_university_module_dependencies dep where dep.module_version_id=p_module and dep.status='published'
 and not exists(select 1 from public.vc_university_module_progress mp where mp.enrollment_id=p_enrollment and mp.module_version_id=dep.depends_on_module_version_id and mp.completed_at is not null)) then raise exception 'previous_module_required'; end if;
 select dv.* into d from public.vc_university_evidence_definition_versions dv
 join public.vc_university_evidence_definitions def on def.evidence_definition_id=dv.evidence_definition_id
 join public.vc_university_module_requirements r on r.module_version_id=p_module and r.status='published' and r.requirement_type='evidence_completed'
 and r.configuration->>'evidence_definition_version_id'=dv.evidence_definition_version_id::text
 where def.module_id=m.module_id and dv.course_id=e.course_id and dv.course_version=e.course_version and dv.status='published';
 if d.evidence_definition_version_id is null then raise exception 'evidence_definition_unavailable'; end if;
 perform pg_advisory_xact_lock(hashtext(p_enrollment::text||':'||d.evidence_definition_version_id::text));
 select * into s from public.vc_university_evidence_submissions where enrollment_id=p_enrollment and evidence_definition_version_id=d.evidence_definition_version_id for update;
 if s.submission_id is null then
 if p_expected_version<>0 then raise exception 'draft_version_conflict'; end if;
 insert into public.vc_university_evidence_submissions(enrollment_id,learner_id,course_id,course_version,evidence_definition_version_id)
 values(p_enrollment,p_actor,e.course_id,e.course_version,d.evidence_definition_version_id) returning * into s;
 created:=true;
 insert into public.vc_university_academic_audit_log(actor_id,action,entity_type,entity_id)
 values(p_actor,'evidence_draft_created','submission',s.submission_id::text);
 end if;
 if p_action='submit' then
 if p_request_id is null then raise exception 'submission_request_id_required'; end if;
 select * into rev from public.vc_university_evidence_revisions where submission_id=s.submission_id and request_id=p_request_id;
 if rev.evidence_revision_id is not null then
 if rev.structured_data is distinct from p_payload then raise exception 'idempotency_payload_conflict'; end if;
 return jsonb_build_object('submission',to_jsonb(s),'revision_id',rev.evidence_revision_id,'idempotent',true); end if;
 end if;
 if s.status not in ('draft','revision_requested') then raise exception 'submission_locked'; end if;
 if p_expected_version is null or s.draft_version<>p_expected_version then raise exception 'draft_version_conflict'; end if;
 if jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>65536 then raise exception 'invalid_draft'; end if;
 if p_action='draft' then
 update public.vc_university_evidence_submissions set draft_data=p_payload,draft_version=draft_version+1,updated_at=now() where submission_id=s.submission_id returning * into s;
 return jsonb_build_object('submission',to_jsonb(s)); end if;
 if not public.vc_university_validate_evidence(d.form_schema,p_payload) then raise exception 'evidence_structure_invalid'; end if;
 ev:=case when s.current_revision=0 then 'evidence_submitted' else 'evidence_resubmitted' end;
 insert into public.vc_university_evidence_revisions(submission_id,revision,content,structured_data,authored_by,request_id)
 values(s.submission_id,s.current_revision+1,'Structured evidence; see structured_data',p_payload,p_actor,p_request_id) returning * into rev;
 update public.vc_university_evidence_submissions set draft_data=p_payload,draft_version=draft_version+1,current_revision=s.current_revision+1,
 status=case when s.current_revision=0 then 'submitted' else 'resubmitted' end,submitted_at=now(),updated_at=now(),
 review_selected=case when d.validation_mode='human_required' then true when d.validation_mode='sampled' then
 review_selected or (get_byte(decode(substr(md5(submission_id::text),1,2),'hex'),0)*100/256)<coalesce((d.validation_policy->>'sample_percent')::integer,0) else false end
 where submission_id=s.submission_id returning * into s;
 sufficient:=d.validation_mode in ('guided','structural','sampled') and d.validation_policy->>'sufficiency'='on_submission';
 perform public.vc_university_evidence_requirement(s.submission_id,sufficient);
 insert into public.vc_university_academic_audit_log(actor_id,action,entity_type,entity_id,after_state,request_id)
 values(p_actor,ev,'submission',s.submission_id::text,jsonb_build_object('revision_id',rev.evidence_revision_id,'status',s.status,'validation_mode',d.validation_mode),p_request_id);
 return jsonb_build_object('submission',to_jsonb(s),'revision_id',rev.evidence_revision_id,'requirement_satisfied',sufficient);
end $$;

create or replace function public.vc_university_evidence_review(p_actor uuid,p_submission uuid,p_revision uuid,p_decision text,p_feedback text)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare s public.vc_university_evidence_submissions%rowtype; d public.vc_university_evidence_definition_versions%rowtype; rev uuid;
begin
 select * into s from public.vc_university_evidence_submissions where submission_id=p_submission for update;
 if not vc_private.vc_university_teacher_can_review(p_actor,p_submission) then raise exception 'evidence_review_denied'; end if;
 select evidence_revision_id into rev from public.vc_university_evidence_revisions where submission_id=p_submission and revision=s.current_revision;
 if rev is distinct from p_revision then raise exception 'review_revision_stale'; end if;
 if p_decision not in ('under_review','revision_requested','approved') or length(btrim(p_feedback)) not between 3 and 4000 then raise exception 'invalid_review'; end if;
 if s.status not in ('submitted','resubmitted','under_review') then raise exception 'review_state_conflict'; end if;
 select * into d from public.vc_university_evidence_definition_versions where evidence_definition_version_id=s.evidence_definition_version_id;
 insert into public.vc_university_evidence_reviews(submission_id,evidence_revision_id,reviewer_id,decision,feedback,rubric_version)
 values(p_submission,p_revision,p_actor,p_decision,btrim(p_feedback),d.rubric_version);
 update public.vc_university_evidence_submissions set status=p_decision,approved_at=case when p_decision='approved' then now() else null end,updated_at=now() where submission_id=p_submission;
 -- Sampling is advisory when sufficiency is on_submission; mandatory review waits for approval.
 if d.validation_policy->>'sufficiency'='on_approval' then perform public.vc_university_evidence_requirement(p_submission,p_decision='approved'); end if;
 insert into public.vc_university_academic_audit_log(actor_id,action,entity_type,entity_id,after_state)
 values(p_actor,case p_decision when 'revision_requested' then 'evidence_revision_requested' when 'approved' then 'evidence_approved' else 'evidence_under_review' end,
 'submission',p_submission::text,jsonb_build_object('revision_id',p_revision,'status',p_decision));
 return jsonb_build_object('submission_id',p_submission,'revision_id',p_revision,'status',p_decision);
end $$;

-- Canonical queue enforces scope even when invoked with service credentials.
create or replace function public.vc_university_evidence_queue(p_actor uuid,p_course text)
returns jsonb language sql stable security invoker set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('submission_id',s.submission_id,'status',s.status,'current_revision',s.current_revision,
 'evidence_revision_id',rev.evidence_revision_id,'structured_data',rev.structured_data,'definition',to_jsonb(d),'module_no',m.module_no,'submitted_at',s.submitted_at)), '[]'::jsonb)
 from public.vc_university_evidence_submissions s
 join public.vc_university_evidence_definition_versions d on d.evidence_definition_version_id=s.evidence_definition_version_id
 join public.vc_university_evidence_definitions def on def.evidence_definition_id=d.evidence_definition_id
 join public.vc_university_modules m on m.module_id=def.module_id
 join public.vc_university_evidence_revisions rev on rev.submission_id=s.submission_id and rev.revision=s.current_revision
 where s.course_id=p_course and vc_private.vc_university_teacher_can_review(p_actor,s.submission_id);
$$;
revoke all on function public.vc_university_validate_evidence_fields(jsonb,jsonb), public.vc_university_validate_evidence(jsonb,jsonb),
 public.vc_university_evidence_requirement(uuid,boolean), public.vc_university_evidence_write(uuid,uuid,uuid,text,jsonb,integer,uuid),
 public.vc_university_evidence_review(uuid,uuid,uuid,text,text), public.vc_university_evidence_queue(uuid,text),
 public.vc_university_guard_evidence_definition() from public,anon,authenticated;
grant execute on function public.vc_university_validate_evidence_fields(jsonb,jsonb), public.vc_university_validate_evidence(jsonb,jsonb),
 public.vc_university_evidence_requirement(uuid,boolean), public.vc_university_evidence_write(uuid,uuid,uuid,text,jsonb,integer,uuid),
 public.vc_university_evidence_review(uuid,uuid,uuid,text,text), public.vc_university_evidence_queue(uuid,text),
 public.vc_university_guard_evidence_definition() to service_role;

-- Only E01–E09 definitions and draft requirements. Course publication is out of scope.

insert into public.vc_university_evidence_definitions(course_id,module_id,evidence_key)
select 'inteligencia-emocional-aplicada',module_id,'e01' from public.vc_university_modules where course_id='inteligencia-emocional-aplicada' and module_no=1
on conflict(course_id,evidence_key) do nothing;
insert into public.vc_university_evidence_definition_versions(evidence_definition_id,course_id,course_version,title,prompt,validation_mode,rubric_version,form_schema,validation_policy,status)
select evidence_definition_id,course_id,'1.0','Mapa da Reação Automática','Permite cenário seguro ou hipotético. A intensidade é subjetiva; emoções não são classificadas como certas ou erradas.','guided','structural-1','{"version": 1, "privacy_notice": "Compartilhe apenas as informações necessárias para demonstrar sua aprendizagem. Não informe nomes completos, documentos, diagnósticos, dados médicos, informações íntimas de terceiros, dados empresariais confidenciais ou qualquer informação que possa causar exposição indevida. Quando necessário, altere nomes, detalhes ou utilize um cenário equivalente.", "sections": [{"section_key": "contexto", "label": "Contexto e percepção", "repeatable": false, "min_items": null, "max_items": null, "fields": [{"field_key": "contexto", "type": "textarea", "label": "Contexto", "help_text": "Descreva apenas o necessário para demonstrar sua aprendizagem.", "required": true, "min": 3, "max": 1200, "repeatable": false, "privacy_hint": "Utilize um cenário equivalente ou detalhes anonimizados.", "validation_rules": {"trim": true}}, {"field_key": "fato_observavel", "type": "textarea", "label": "Fato observável", "help_text": "Descreva apenas o necessário para demonstrar sua aprendizagem.", "required": true, "min": 3, "max": 1200, "repeatable": false, "privacy_hint": "Utilize um cenário equivalente ou detalhes anonimizados.", "validation_rules": {"trim": true}}, {"field_key": "interpretacao", "type": "textarea", "label": "Interpretacao", "help_text": "Descreva apenas o necessário para demonstrar sua aprendizagem.", "required": true, "min": 3, "max": 1200, "repeatable": false, "privacy_hint": "Utilize um cenário equivalente ou detalhes anonimizados.", "validation_rules": {"trim": true}}, {"field_key": "emocao_percebida", "type": "textarea", "label": "Emoção percebida", "help_text": "Descreva apenas o necessário para demonstrar sua aprendizagem.", "required": true, "min": 3, "max": 1200, "repeatable": false, "privacy_hint": "Utilize um cenário equivalente ou detalhes anonimizados.", "validation_rules": {"trim": true}}, {"field_key": "intensidade_0_10", "type": "number", "label": "Intensidade percebida (0–10)", "help_text": "Estimativa subjetiva. Não é score psicológico ou diagnóstico.", "required": true, "min": 0, "max": 10, "repeatable": false, "privacy_hint": "Utilize um cenário equivalente ou detalhes anonimizados.", "validation_rules": {"integer": true}}, {"field_key": "sinais_corporais", "type": "textarea", "label": "Sinais corporais", "help_text": "Descreva apenas o necessário para demonstrar sua aprendizagem.", "required": true, "min": 3, "max": 1200, "repeatable": false, "privacy_hint": "Utilize um cenário equivalente ou detalhes anonimizados.", "validation_rules": {"trim": true}}]}, {"section_key": "resposta", "label": "Resposta e consequências", "repeatable": false, "min_items": null, "max_items": null, "fields": [{"field_key": "impulso_tendencia", "type": "textarea", "label": "Impulso tendencia", "help_text": "Descreva apenas o necessário para demonstrar sua aprendizagem.", "required": true, "min": 3, "max": 1200, "repeatable": false, "privacy_hint": "Utilize um cenário equivalente ou detalhes anonimizados.", "validation_rules": {"trim": true}}, {"field_key": "comportamento_realizado", "type": "textarea", "label": "Comportamento realizado", "help_text": "Descreva apenas o necessário para demonstrar sua aprendizagem.", "required": true, "min": 3, "max": 1200, "repeatable": false, "privacy_hint": "Utilize um cenário equivalente ou detalhes anonimizados.", "validation_rules": {"trim": true}}, {"field_key": "consequencia_imediata", "type": "textarea", "label": "Consequencia imediata", "help_text": "Descreva apenas o necessário para demonstrar sua aprendizagem.", "required": true, "min": 3, "max": 1200, "repeatable": false, "privacy_hint": "Utilize um cenário equivalente ou detalhes anonimizados.", "validation_rules": {"trim": true}}, {"field_key": "consequencia_posterior", "type": "textarea", "label": "Consequencia posterior", "help_text": "Descreva apenas o necessário para demonstrar sua aprendizagem.", "required": true, "min": 3, "max": 1200, "repeatable": false, "privacy_hint": "Utilize um cenário equivalente ou detalhes anonimizados.", "validation_rules": {"trim": true}}, {"field_key": "reflexao_final", "type": "textarea", "label": "Reflexao final", "help_text": "Descreva apenas o necessário para demonstrar sua aprendizagem.", "required": true, "min": 3, "max": 1200, "repeatable": false, "privacy_hint": "Utilize um cenário equivalente ou detalhes anonimizados.", "validation_rules": {"trim": true}}]}]}'::jsonb,'{"sufficiency": "on_submission", "sample_percent": 0, "teacher_review": false}'::jsonb,'draft'
from public.vc_university_evidence_definitions where course_id='inteligencia-emocional-aplicada' and evidence_key='e01'
on conflict(evidence_definition_id,course_version,revision) do nothing;
insert into public.vc_university_module_requirements(course_id,course_version,module_version_id,requirement_key,requirement_type,configuration,required,position,status)
select mv.course_id,mv.course_version,mv.module_version_id,'evidence-e01','evidence_completed',jsonb_build_object('evidence_definition_version_id',dv.evidence_definition_version_id),true,1,'draft'
from public.vc_university_module_versions mv
join public.vc_university_evidence_definitions def on def.module_id=mv.module_id
join public.vc_university_evidence_definition_versions dv on dv.evidence_definition_id=def.evidence_definition_id and dv.course_version=mv.course_version
