select evidence_definition_id,course_id,'1.0','Decisão Estruturada','Utilize decisão cotidiana ou profissional apropriada.','sampled','structural-1','{"version": 1, "privacy_notice": "Compartilhe apenas as informações necessárias para demonstrar sua aprendizagem. Não informe nomes completos, documentos, diagnósticos, dados médicos, informações íntimas de terceiros, dados empresariais confidenciais ou qualquer informação que possa causar exposição indevida. Quando necessário, altere nomes, detalhes ou utilize um cenário equivalente.", "sections": [{"section_key": "3t", "label": "3T", "repeatable": false, "min_items": null, "max_items": null, "fields": [{"field_key": "tempo_disponivel", "type": "textarea", "label": "Tempo disponivel", "help_text": "Descreva apenas o necessário para demonstrar sua aprendizagem.", "required": true, "min": 3, "max": 1200, "repeatable": false, "privacy_hint": "Utilize um cenário equivalente ou detalhes anonimizados.", "validation_rules": {"trim": true}}, {"field_key": "tamanho_da_decisao", "type": "textarea", "label": "Tamanho da decisao", "help_text": "Descreva apenas o necessário para demonstrar sua aprendizagem.", "required": true, "min": 3, "max": 1200, "repeatable": false, "privacy_hint": "Utilize um cenário equivalente ou detalhes anonimizados.", "validation_rules": {"trim": true}}, {"field_key": "temperatura_emocional", "type": "textarea", "label": "Temperatura emocional", "help_text": "Descreva apenas o necessário para demonstrar sua aprendizagem.", "required": true, "min": 3, "max": 1200, "repeatable": false, "privacy_hint": "Utilize um cenário equivalente ou detalhes anonimizados.", "validation_rules": {"trim": true}}]}, {"section_key": "decide_fatos", "label": "DECIDE — fatos e alternativas", "repeatable": false, "min_items": null, "max_items": null, "fields": [{"field_key": "definir_decisao", "type": "textarea", "label": "Definir decisao", "help_text": "Descreva apenas o necessário para demonstrar sua aprendizagem.", "required