from public.vc_university_evidence_definitions where course_id='inteligencia-emocional-aplicada' and evidence_key='e09'
on conflict(evidence_definition_id,course_version,revision) do nothing;
insert into public.vc_university_module_requirements(course_id,course_version,module_version_id,requirement_key,requirement_type,configuration,required,position,status)
select mv.course_id,mv.course_version,mv.module_version_id,'evidence-e09','evidence_completed',jsonb_build_object('evidence_definition_version_id',dv.evidence_definition_version_id),true,1,'draft'
from public.vc_university_module_versions mv
join public.vc_university_evidence_definitions def on def.module_id=mv.module_id
join public.vc_university_evidence_definition_versions dv on dv.evidence_definition_id=def.evidence_definition_id and dv.course_version=mv.course_version
where mv.course_id='inteligencia-emocional-aplicada' and mv.course_version='1.0' and def.evidence_key='e09'
on conflict(course_id,course_version,module_version_id,requirement_key) do nothing;

-- Draft text is private even from an assigned reviewer; they see immutable submitted revisions.
revoke select on public.vc_university_evidence_submissions from authenticated;
grant select(submission_id,enrollment_id,learner_id,course_id,course_version,evidence_definition_version_id,status,current_revision,contains_sensitive_data,submitted_at,approved_at,created_at,updated_at,review_selected,draft_version)
 on public.vc_university_evidence_submissions to authenticated;
